import asyncio
import json

from playwright.async_api import async_playwright

from src.browser_runtime.page_ops.apply.decision import resolve_application_page
from src.browser_runtime.page_ops.apply.flow import page_has_application_form
from src.llm import get_llm_client

URL = "https://jll.wd1.myworkdayjobs.com/jllcareers/job/Creve-Coeur-MO/Specialist--HVAC-Technician_REQ495034"
FORM_JS = """
() => {
    const controls = Array.from(document.querySelectorAll('input, select, textarea, [role="textbox"], [role="combobox"], [role="listbox"]'));
    return controls.filter((el) => {
        if (!(el instanceof HTMLElement)) return false;
        const type = (el.getAttribute("type") || "").toLowerCase();
        if (type === "hidden" || type === "search" || type === "submit" || type === "button") return false;
        const rect = el.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0;
    }).map((el) => ({ tag: el.tagName, type: el.getAttribute("type"), name: (el.getAttribute("name")||"").slice(0,30), aria: (el.getAttribute("aria-label")||"").slice(0,40) }));
}
"""


async def main() -> None:
    model = get_llm_client()
    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True)
        page = await browser.new_page()
        apply_url = f"{URL}/apply"
        response = await page.goto(apply_url, wait_until="domcontentloaded", timeout=60000)
        print("apply HTTP", response.status if response else None)
        for wait in (0, 2, 5, 10):
            if wait:
                await page.wait_for_timeout(wait * 1000)
            controls = await page.evaluate(FORM_JS)
            print(f"t+{wait}s url={page.url} form={await page_has_application_form(page)} controls={len(controls)}")
            if wait == 10:
                print("  sample:", json.dumps(controls[:5]))
                decision = await resolve_application_page(page, model=model)
                print("  DECISION:", decision.decision.value, decision.candidate_url, decision.evidence)
        await browser.close()


asyncio.run(main())

